{
  "name": "opencode-tts-plugin",
  "version": "0.1.1",
  "description": "Lee en voz alta el informe del último turno en la TUI de opencode. Solo Windows.",
  "type": "module",
  "license": "MIT",
  "author": "Asura7170 (https://github.com/Asura7170)",
  "homepage": "https://github.com/Asura7170/OpenCode-TTS-Plugin#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Asura7170/OpenCode-TTS-Plugin.git",
    "directory": ".opencode/plugins/tts"
  },
  "bugs": {
    "url": "https://github.com/Asura7170/OpenCode-TTS-Plugin/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tts",
    "text-to-speech",
    "windows",
    "powershell",
    "sapi",
    "tui"
  ],
  "os": [
    "win32"
  ],
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx"
  },
  "files": [
    "index.ts",
    "tui.tsx",
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "bun test",
    "prepublishOnly": "bun test"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": ">=2.0.32 <3"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6 <1",
    "@opentui/solid": ">=0.6.6 <1",
    "solid-js": ">=1.9.0 <2"
  }
}
